+// positionFunc is a XPath Node Set functions position().
+func positionFunc() func(query, iterator) interface{} {
+	return func(q query, t iterator) interface{} {
+		var (
+			count = 1
+			node  = t.Current().Copy()
+		)
+		test := predicate(q)
+		for node.MoveToPrevious() {
+			if test(node) {
+				count++
+			}
+		}
+		return float64(count)
+	}
